(async()=>{if(new URLSearchParams(location.search).get('profile')!=='fire-check')return;while(!window.EmberQA)await new Promise(r=>setTimeout(r,100));const q=EmberQA,D=SurvivalData,W=EmberTerrain;document.getElementById('welcome').hidden=true;q.setPlaying(false);const report=document.createElement('pre');report.id='fire-report';report.style='position:fixed;top:12px;left:12px;background:#fff;color:#234;padding:12px;z-index:100';document.body.append(report);const result={},check=(k,v)=>{result[k]=!!v;report.textContent=JSON.stringify(result,null,2);if(!v)throw Error(k);};try{
const x=0,z=28,y=W.ground(x,z);q.apply({...D.fresh(),x,z:z+3,y:W.ground(x,z+3),worldTime:20/24*720,weatherMode:'clear',automaticTime:false,inventory:{wood:1},structures:[{id:'fire-test',type:'campfire',x,y,z,lit:false,progress:1,items:{}}]});const s=q.state.structures[0],g=q.world.dynamic.children.find(g=>g.userData.flame);check('unlitHidden',!g.userData.flame.visible&&!g.userData.light.visible);q.campMenu(s);document.querySelector('[data-action="ignite:'+s.id+'"]').click();q.close(false);check('ignitionConsumesWood',s.lit&&!q.state.inventory.wood);check('visibleFlameAndLight',g.userData.flame.isSprite&&g.userData.flame.visible&&g.userData.light.visible);while(!q.world.fireMaterial.map.image?.complete)await new Promise(r=>setTimeout(r,100));check('generatedAtlasLoaded',q.world.fireMaterial.map.image.naturalWidth===1640);check('all60Frames',new Set(Array.from({length:60},(_,i)=>Math.floor(SurvivalFire.frameAt((i+.01)/45)))).size===60);check('wrapsToStart',SurvivalFire.frameAt(60/45)===0);q.world.updateFires(.1);const before=g.userData.light.intensity;q.world.updateFires(.2);check('lightFlickers',before!==g.userData.light.intensity);check('sharedTexture',q.world.fireVisual(s).material===g.userData.flame.material);
q.camera.position.set(x+2.8,y+2,z+3.2);q.camera.lookAt(x,y+.7,z);q.sky.update(q.state,0,true);result.complete=true;report.textContent=JSON.stringify(result,null,2);const hide=document.createElement('button');hide.textContent='確認表示を閉じる';hide.style='position:fixed;top:12px;right:12px;z-index:200';hide.onclick=()=>{hide.remove();report.hidden=true;};document.body.append(hide);function animate(){q.world.updateFires(performance.now()/1000);q.renderer.render(q.scene,q.camera);requestAnimationFrame(animate);}animate();
}catch(e){report.textContent+='\nFAIL '+e.stack;}})();
